        { const uint _a = (offset_src1 + idx[0] * stride_src10 + idx[1] * stride_src11 + idx[2] * stride_src12 + idx[3] * stride_src13); bits = (src1.Load(_a & ~3u) >> ((_a & 3u) * 8u)) & 0xFFu; }
