#define LOAD_F16(buf, i)     f16tof32((uint) (buf).Load<uint16_t>((i) * 2))
#define STORE_F16(buf, i, v) (buf).Store<uint16_t>((i) * 2, (uint16_t) f32_to_f16_rne(v))
#elif defined(GGML_D3D11)
