        const uint blk  = sb / 8;
        const uint s    = sb % 8;
        const uint base = (src0_base + blk) * 74;
        uint dbits, sc;
        LOAD_U16_UNALIGNED(src0, base, dbits);
        LOAD_U32_UNALIGNED(src0, base + 66 + s, sc);
