    uint offset_k;
    uint offset_v;
    uint offset_r;
    uint offset_tf;
    uint offset_td;
    uint offset_s;
    uint offset_dst;
    uint cc;          // C = HEADS * head_size
    uint hs;          // head_size
    uint tps;         // tokens per sequence, T / n_seqs
    uint s_off;       // C * T, the element offset of the state area inside dst
    uint n_jobs;      // n_seqs * HEADS * head_size
